def _build_scenarios_expansion(start_id: int = 37) -> list:
    out = []
    curr_id = start_id

    for sc_type, ex_type, title, prompt, prompt_ru, sol, opts, expl_ru, expr_tuple, diff in SCENARIO_SPECS:
        en_e, ru_e, ctx_e = expr_tuple
        out.append({
            "id": curr_id,
            "type": sc_type,
            "exercise_type": ex_type,
            "title": title,
            "prompt": prompt,
            "prompt_ru": prompt_ru,
            "solution": sol,
            "options": opts,
            "explanation_ru": expl_ru,
            "useful_expressions": [
                expr(en_e, ru_e, ctx_e),
                expr("In practice, this keeps our engineering communication clear.", "На практике это делает нашу инженерную коммуникацию чёткой.", "Профессиональное общение"),
            ],
            "difficulty": diff,
        })
        curr_id += 1

    for sc_type, items in EXISTING_CONTEXT_EXPANSIONS.items():
        for ex_type, title, prompt, prompt_ru, sol, opts, expl_ru, expr_tuple, diff in items:
            en_e, ru_e, ctx_e = expr_tuple
            out.append({
                "id": curr_id,
                "type": sc_type,
                "exercise_type": ex_type,
                "title": title,
                "prompt": prompt,
                "prompt_ru": prompt_ru,
                "solution": sol,
                "options": opts,
                "explanation_ru": expl_ru,
                "useful_expressions": [
                    expr(en_e, ru_e, ctx_e),
                    expr("Clear technical English prevents costly misunderstandings.", "Точный технический английский предотвращает дорогостоящие недоразумения.", "IT-коммуникация"),
                ],
                "difficulty": diff,
            })
            curr_id += 1

    return out


