def _build_work_phrases_expansion(start_id: int = 65) -> list:
    phrases = []
    curr_id = start_id

    # 1. Add 18 phrases to each of the 8 existing contexts (8 + 18 = 26 per context)
    for cat, items in ADDITIONAL_PHRASE_TEMPLATES_PER_CONTEXT:
        for en_p, ru_p, ctx_p, diff_p in items:
            phrases.append((curr_id, cat, en_p, ru_p, ctx_p, diff_p))
            curr_id += 1

    # 2. Add 8 + 18 = 26 phrases for each of the 4 new contexts
    for cat in ("SYSTEM_DESIGN_INTERVIEW", "INCIDENT_POST_MORTEM", "SALARY_NEGOTIATION", "CLIENT_COMMUNICATION"):
        combined = NEW_CONTEXT_BASE_PHRASES[cat] + NEW_CONTEXT_EXTRA_PHRASES[cat]
        assert len(combined) == 26, f"Expected 26 phrases for {cat}, got {len(combined)}"
        for en_p, ru_p, ctx_p, diff_p in combined:
            phrases.append((curr_id, cat, en_p, ru_p, ctx_p, diff_p))
            curr_id += 1

    return phrases


SCENARIOS_V3_EXPANSION = _build_scenarios_expansion(start_id=37)
WORK_PHRASES_V3_EXPANSION = _build_work_phrases_expansion(start_id=65)
